'use strict';

/**
* Return the index of the first element in a double-precision floating-point strided array which is less than or equal to a corresponding element in another double-precision floating-point strided array.
*
* @module @stdlib/blas/ext/base/dfirst-index-less-than-equal
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dfirstIndexLessThanEqual = require( '@stdlib/blas/ext/base/dfirst-index-less-than-equal' );
*
* var x = new Float64Array( [ 2.0, 2.0, 2.0, 2.0 ] );
* var y = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* var idx = dfirstIndexLessThanEqual( x.length, x, 1, y, 1 );
* // returns 1
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dfirstIndexLessThanEqual = require( '@stdlib/blas/ext/base/dfirst-index-less-than-equal' );
*
* var x = new Float64Array( [ 2.0, 2.0, 2.0, 2.0 ] );
* var y = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* var idx = dfirstIndexLessThanEqual.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns 1
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dfirstIndexLessThanEqual;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dfirstIndexLessThanEqual = main;
} else {
	dfirstIndexLessThanEqual = tmp;
}


// EXPORTS //

module.exports = dfirstIndexLessThanEqual;

// exports: { "ndarray": "dfirstIndexLessThanEqual.ndarray" }
